//! BIG5, EUC-KR, CP949, CP932, CP936 and GB18030, built in (no charmap file needed): tables generated by
//! `cargo xtask encodings-gen` (`cjk_tables`) from public mapping tables plus the reference
//! library's variant of each, recorded as data from a black-box probe of its whole code space
//! (`spec/encoding/reference/*.tsv`). The code here is the same for every set; only GB18030's
//! four-byte sequences have code of their own.
//!
//! **Bytes.** 0x00..=0x7F are ASCII. A byte 0x80..=0xFF is a character, a lead byte or invalid
//! (`Set::high`). A lead and a trail byte are a cell of the set's table; GB18030 also reads a
//! lead, a digit 0x30..=0x39, a lead and a digit as one of its four-byte sequences: a pointer
//! mapped by the GB18030 ranges (BMP) or linearly from U+10000 (pointers 189000..=1237575).
//!
//! **Invalid input (probed).** A lead at the end of the input waits for more (as do a GB18030
//! lead and digit, with or without a third byte). An invalid two-byte sequence is skipped by
//! `//IGNORE` as two bytes, or as the lead alone after the trail bytes the set's variant lists
//! for that lead (`skip1`). An invalid GB18030 four-byte sequence is skipped as four bytes when
//! its third byte is a lead, else as three. With `//IGNORE` on the target, CP932 reports skipped
//! input as success; the others end with `EILSEQ` (`Set::ignore_error`).

#![allow(clippy::arithmetic_side_effects)] // bytes, pointers below 1237576, code points below 0x110000

use super::Dec;
use super::cjk_tables::{BIG5, CP932, CP936, CP949, EUC_KR, GB18030, GB18030_RANGES};

/// One set's tables (generated in `cjk_tables`).
pub(super) struct Set {
    /// The bytes 0x80..=0xFF: a code point, [`LEAD`] or [`BAD`].
    pub(super) high: [u16; 128],
    /// The first lead byte; `rows`, `skip_row` start there.
    pub(super) lead_lo: u8,
    /// Per lead: the offset of its cells in `cells` and its first and last trail byte.
    pub(super) rows: &'static [(u16, u8, u8)],
    /// The two-byte cells, 0 for none.
    pub(super) cells: &'static [u16],
    /// Bitmaps of trail bytes after which an invalid sequence is skipped one byte.
    pub(super) skip1: &'static [[u32; 8]],
    /// Per lead: its bitmap in `skip1`.
    pub(super) skip_row: &'static [u8],
    /// Per 64 BMP code points: its page in `codes`.
    pub(super) pages: &'static [u16],
    /// The encoding of each code point: one byte (below 0x100), two bytes, 0 for none or
    /// [`BLOCKED`].
    pub(super) codes: &'static [u16],
    /// GB18030: four-byte pointers whose code point is not the ranges' (pointer, code point).
    pub(super) four: &'static [(u32, u32)],
    /// GB18030: code points written as a four-byte pointer other than the ranges give.
    pub(super) four_enc: &'static [(u32, u32)],
    /// Whether input `//IGNORE` skipped makes the call end with `EILSEQ`.
    pub(super) ignore_error: bool,
}

const LEAD: u16 = 0xFFFF;
const BAD: u16 = 0xFFFE;
const BLOCKED: u16 = 0xFFFF;

/// The built-in sets.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Which {
    /// BIG5 (also CP950).
    Big5,
    /// EUC-KR.
    EucKr,
    /// CP932 (Windows-31J).
    Cp932,
    /// CP936 (GBK).
    Cp936,
    /// GB18030.
    Gb18030,
    /// CP949 (Unified Hangul Code, UHC): EUC-KR plus the rest of the modern Hangul syllables.
    Cp949,
}

impl Which {
    /// Every set, in descriptor tag order (a new set goes last: the tags of the others stay).
    pub(super) const ALL: [Which; 6] = [Which::Big5, Which::EucKr, Which::Cp932, Which::Cp936, Which::Gb18030, Which::Cp949];

    fn set(self) -> &'static Set {
        match self {
            Which::Big5 => &BIG5,
            Which::EucKr => &EUC_KR,
            Which::Cp949 => &CP949,
            Which::Cp932 => &CP932,
            Which::Cp936 => &CP936,
            Which::Gb18030 => &GB18030,
        }
    }

    /// Whether input `//IGNORE` skipped makes the call end with `EILSEQ`.
    pub(super) fn ignore_error(self) -> bool {
        self.set().ignore_error
    }
}

/// The code point of GB18030 four-byte pointer `p` (None: no character).
fn four_cp(p: u32) -> Option<u32> {
    if let Ok(i) = GB18030.four.binary_search_by_key(&p, |&(q, _)| q) {
        return GB18030.four.get(i).map(|&(_, c)| c);
    }
    if (189_000..=1_237_575).contains(&p) {
        return Some(0x1_0000 + p - 189_000);
    }
    if p > 39_419 {
        return None;
    }
    let i = GB18030_RANGES.partition_point(|&(q, _)| q <= p).checked_sub(1)?;
    GB18030_RANGES.get(i).map(|&(q, c)| c + p - q)
}

/// The four-byte pointer GB18030 writes `c` as, if any.
fn four_ptr(c: u32) -> Option<u32> {
    if let Ok(i) = GB18030.four_enc.binary_search_by_key(&c, |&(x, _)| x) {
        return GB18030.four_enc.get(i).map(|&(_, p)| p);
    }
    let p = if c >= 0x1_0000 {
        189_000 + c - 0x1_0000
    } else {
        let i = GB18030_RANGES.partition_point(|&(_, x)| x <= c).checked_sub(1)?;
        GB18030_RANGES.get(i).map(|&(q, x)| q + c - x)?
    };
    (four_cp(p) == Some(c)).then_some(p)
}

fn decode_four(input: &[u8]) -> Dec {
    let (Some(&b0), Some(&b1)) = (input.first(), input.get(1)) else { return Dec::Incomplete };
    let (Some(&b2), Some(&b3)) = (input.get(2), input.get(3)) else { return Dec::Incomplete };
    if !(0x81..=0xFE).contains(&b2) {
        return Dec::Invalid(3);
    }
    if !(0x30..=0x39).contains(&b3) {
        return Dec::Invalid(4);
    }
    let p = (u32::from(b0 - 0x81) * 10 + u32::from(b1 - 0x30)) * 1260 + u32::from(b2 - 0x81) * 10 + u32::from(b3 - 0x30);
    four_cp(p).map_or(Dec::Invalid(4), |c| Dec::Char(c, 4))
}

/// Decode one character.
pub(super) fn decode(w: Which, input: &[u8]) -> Dec {
    let s = w.set();
    let Some(&b0) = input.first() else { return Dec::Incomplete };
    if b0 < 0x80 {
        return Dec::Char(u32::from(b0), 1);
    }
    match s.high.get(usize::from(b0 - 0x80)).copied().unwrap_or(BAD) {
        BAD => return Dec::Invalid(1),
        LEAD => {}
        c => return Dec::Char(u32::from(c), 1),
    }
    let Some(&b1) = input.get(1) else { return Dec::Incomplete };
    if w == Which::Gb18030 && (0x30..=0x39).contains(&b1) {
        return decode_four(input);
    }
    let r = usize::from(b0.wrapping_sub(s.lead_lo));
    if let Some(&(off, first, last)) = s.rows.get(r) {
        if (first..=last).contains(&b1) {
            if let Some(&c) = s.cells.get(usize::from(off) + usize::from(b1 - first)) {
                if c != 0 {
                    return Dec::Char(u32::from(c), 2);
                }
            }
        }
    }
    let map = s.skip_row.get(r).and_then(|&k| s.skip1.get(usize::from(k)));
    let one = map.and_then(|m| m.get(usize::from(b1 / 32))).is_some_and(|&word| word & (1 << (b1 % 32)) != 0);
    Dec::Invalid(if one { 1 } else { 2 })
}

/// Encode `c`; `None` if the set has no character for it. A tag character (U+E0000..=U+E007F)
/// the set cannot write is written as nothing (probed: GB18030 writes them, the others drop them).
pub(super) fn encode(w: Which, c: u32, out: &mut [u8; 8]) -> Option<usize> {
    let n = encode_set(w, c, out);
    if n.is_none() && (0xE0000..=0xE007F).contains(&c) {
        return Some(0);
    }
    n
}

fn encode_set(w: Which, c: u32, out: &mut [u8; 8]) -> Option<usize> {
    if c < 0x80 {
        out[0] = u8::try_from(c).ok()?;
        return Some(1);
    }
    let s = w.set();
    if c <= 0xFFFF {
        let page = usize::from(*s.pages.get(usize::try_from(c >> 6).ok()?)?);
        let v = *s.codes.get(page * 64 + usize::try_from(c & 63).ok()?)?;
        match v {
            BLOCKED => return None,
            0 => {}
            1..=0xFF => {
                out[0] = u8::try_from(v).ok()?;
                return Some(1);
            }
            _ => {
                out[..2].copy_from_slice(&v.to_be_bytes());
                return Some(2);
            }
        }
    }
    if w != Which::Gb18030 {
        return None;
    }
    let p = four_ptr(c)?;
    let b = |v: u32| u8::try_from(v).unwrap_or(0);
    out[..4].copy_from_slice(&[b(p / 12600 + 0x81), b(p / 1260 % 10 + 0x30), b(p / 10 % 126 + 0x81), b(p % 10 + 0x30)]);
    Some(4)
}

#[cfg(test)]
#[allow(clippy::indexing_slicing, clippy::unwrap_used)]
mod tests {
    use super::*;

    fn enc(w: Which, c: u32) -> Option<Vec<u8>> {
        let mut out = [0u8; 8];
        encode(w, c, &mut out).map(|n| out[..n].to_vec())
    }

    /// Every character of every set decodes and encodes back to the bytes it was read from,
    /// except the code points the reference writes another way (s6_4_c_2), and the number of
    /// characters equals the reference's (probed: two-byte cells plus single bytes 0x80..).
    #[test]
    fn cjk_round_trips() {
        let want = [(Which::Big5, 13911 + 1), (Which::EucKr, 8227 + 32), (Which::Cp949, 17048), (Which::Cp932, 9604 + 63), (Which::Cp936, 21791 + 1), (Which::Gb18030, 23940)];
        for (w, n_want) in want {
            let mut n = 0;
            for v in 0x80..=0xFFFFu32 {
                let seq: Vec<u8> = if v < 0x100 { vec![u8::try_from(v).unwrap()] } else { v.to_be_bytes()[2..].to_vec() };
                if let Dec::Char(c, len) = decode(w, &seq) {
                    if len == seq.len() {
                        n += 1;
                        let back = enc(w, c).unwrap();
                        assert_eq!(decode(w, &back), Dec::Char(c, back.len()), "{w:?} U+{c:04X}");
                    }
                }
            }
            assert_eq!(n, n_want, "{w:?}: characters below four bytes");
        }
    }

    /// GB18030's four-byte area: its ends, a supplementary code point, the probed departures from
    /// the ranges, and the invalid forms (s6_4_c_2, s6_4_f_2_2, s6_4_f_3).
    #[test]
    fn gb18030_four_bytes() {
        let g = Which::Gb18030;
        assert_eq!(decode(g, &[0x81, 0x30, 0x81, 0x30]), Dec::Char(0x80, 4));
        assert_eq!(decode(g, &[0x84, 0x31, 0xA4, 0x39]), Dec::Char(0xFFFF, 4));
        assert_eq!(decode(g, &[0x84, 0x31, 0xA5, 0x30]), Dec::Invalid(4));
        assert_eq!(decode(g, &[0x90, 0x30, 0x81, 0x30]), Dec::Char(0x1_0000, 4));
        assert_eq!(decode(g, &[0xE3, 0x32, 0x9A, 0x35]), Dec::Char(0x10_FFFF, 4));
        assert_eq!(decode(g, &[0xE3, 0x32, 0x9A, 0x36]), Dec::Invalid(4));
        assert_eq!(decode(g, &[0x82, 0x35, 0x90, 0x37]), Dec::Char(0xE81E, 4), "a probed departure");
        assert_eq!(decode(g, &[0x81, 0x30, 0x81]), Dec::Incomplete);
        assert_eq!(decode(g, &[0x81, 0x30, 0x41]), Dec::Incomplete, "waits for a fourth byte");
        assert_eq!(decode(g, &[0x81, 0x30, 0x41, 0x30]), Dec::Invalid(3));
        assert_eq!(decode(g, &[0x81, 0x30, 0x81, 0x41]), Dec::Invalid(4));
        assert_eq!(enc(g, 0x80), Some(vec![0x81, 0x30, 0x81, 0x30]));
        assert_eq!(enc(g, 0x10_FFFF), Some(vec![0xE3, 0x32, 0x9A, 0x35]));
        assert_eq!(enc(g, 0xE81E), Some(vec![0x82, 0x35, 0x90, 0x37]));
        assert_eq!(enc(g, 0x20AC), Some(vec![0xA2, 0xE3]));
        assert_eq!(enc(g, 0xE0001), Some(vec![0xD3, 0x36, 0x95, 0x39]), "a tag character GB18030 can write");
    }

    /// Single bytes, leads and skips that differ between the sets (s6_4_f_2_3, s6_4_f_3).
    #[test]
    fn cjk_bytes_and_skips() {
        assert_eq!(decode(Which::Big5, &[0x80]), Dec::Char(0x80, 1));
        assert_eq!(decode(Which::Big5, &[0xA1]), Dec::Incomplete);
        assert_eq!(decode(Which::Big5, &[0xA1, 0x30]), Dec::Invalid(1));
        assert_eq!(decode(Which::Cp932, &[0xA1]), Dec::Char(0xFF61, 1));
        assert_eq!(decode(Which::Cp932, &[0xF0, 0x40]), Dec::Char(0xE000, 2));
        assert_eq!(decode(Which::Cp936, &[0x80]), Dec::Char(0x20AC, 1));
        assert_eq!(decode(Which::EucKr, &[0xA1, 0x41]), Dec::Invalid(2));
        assert_eq!(decode(Which::Gb18030, &[0x80]), Dec::Invalid(1));
        assert_eq!(enc(Which::EucKr, 0x20A9), Some(vec![0xA3, 0xDC]), "one way");
        assert_eq!(enc(Which::Cp932, 0xA5), Some(vec![0x5C]), "one way");
        assert_eq!(enc(Which::Big5, 0xE0001), Some(vec![]));
        assert!(!Which::Cp932.ignore_error() && Which::Big5.ignore_error());
    }

    /// CP949: a Unified Hangul cell outside EUC-KR, the last cells of row A2, and the byte pair
    /// after them, which CP949.TXT does not assign: an invalid two-byte sequence, nothing
    /// consumed, skipped whole with //IGNORE (s6_4_f_2_3, s6_4_f_3; no reference comparison for
    /// this pair, `iconv_codespace_products.rs` OWN_TEST).
    #[test]
    fn cp949_cells_and_unassigned_pair() {
        let u = Which::Cp949;
        assert_eq!(decode(u, &[0x81, 0x41]), Dec::Char(0xAC02, 2));
        assert_eq!(decode(Which::EucKr, &[0x81, 0x41]), Dec::Invalid(1));
        assert_eq!(decode(u, &[0xA2, 0xE6]), Dec::Char(0x20AC, 2));
        assert_eq!(decode(u, &[0xA2, 0xE7]), Dec::Char(0xAE, 2));
        assert_eq!(decode(u, &[0xA2, 0xE8]), Dec::Invalid(2));
        assert_eq!(decode(u, &[0xA2]), Dec::Incomplete);
        assert_eq!(enc(u, 0xAC02), Some(vec![0x81, 0x41]));
        assert!(u.ignore_error());
    }
}
